import java.time.*;

public class DstMath {
    public static void main(String[] args) {
        ZonedDateTime z = ZonedDateTime.of(2024, 3, 30, 12, 0, 0, 0, ZoneId.of("Europe/Rome"));
        ZonedDateTime p = z.plus(Period.ofDays(1));
        ZonedDateTime d = z.plus(Duration.ofDays(1));
        System.out.println(p.toLocalTime() + " " + d.toLocalTime() + " " + Duration.between(z, p).toHours());
    }
}

import java.time.*;
import java.time.temporal.ChronoUnit;

public class Stamp {
    public static void main(String[] args) {
        ZonedDateTime z = ZonedDateTime.of(2024, 1, 15, 10, 0, 0, 0, ZoneId.of("Europe/Rome"));
        Instant i = z.toInstant();
        System.out.println(i);
        System.out.println(i.plus(1, ChronoUnit.DAYS));
        System.out.println(i.plus(1, ChronoUnit.MONTHS));
    }
}

